class Fail extends Error { constructor(public code: string, public status = 400) { super(code); } }
const now = () => new Date().toISOString();
const clip = (v: unknown, n: number) => String(v ?? "").replace(/[\u0000-\u001f]/g, " ").trim().slice(0, n);
const EMAIL_RX = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const TYPES = ["referral", "accountant", "bookkeeping", "property_management", "attorney", "realtor", "other"];
const TYPE_PT: Record<string, string> = { referral: "Consultor / assessor", accountant: "Contador", bookkeeping: "Bookkeeping", property_management: "Administração de imóveis", attorney: "Advogado", realtor: "Corretor de imóveis", other: "Outro" };
async function sha256(b: Uint8Array | string) { const d = await crypto.subtle.digest("SHA-256", (typeof b === "string" ? new TextEncoder().encode(b) : b) as BufferSource); return Array.from(new Uint8Array(d)).map((x) => x.toString(16).padStart(2, "0")).join(""); }
const mailer = () => nodemailer.createTransport({ host: SMTP_HOST, port: 465, secure: true, auth: { user: SMTP_USER, pass: SMTP_PASS } });
async function bell(kind: string, title: string, body: string, link: string) { await db.from("admin_events").insert({ kind, title: title.slice(0, 300), body: body.slice(0, 2000), link: link.slice(0, 300) }); }
function fmtWhen(iso: string, lang: Lang, tz?: string | null) {
  const loc = lang === "pt" ? "pt-BR" : lang === "es" ? "es" : "en-US";
  const zone = tz && /^[A-Za-z_]+\/[A-Za-z_\/+-]+$/.test(tz) ? tz : "America/New_York";
  try { return new Intl.DateTimeFormat(loc, { timeZone: zone, dateStyle: "full", timeStyle: "short" }).format(new Date(iso)) + " (" + zone.replace(/_/g, " ") + ")"; }
  catch { return new Intl.DateTimeFormat(loc, { timeZone: "America/New_York", dateStyle: "full", timeStyle: "short" }).format(new Date(iso)) + " (Orlando)"; }
}
// secure link to create the password: invite for a new login, recovery when the login already exists
async function accessLink(email: string, portal: string, allowReplace: boolean, partnerId: string) {
  let gen = await db.auth.admin.generateLink({ type: "invite", email, options: { redirectTo: portal } });
  let kind = "invite";
  if (gen.error && /already|registered|exists/i.test(gen.error.message) && allowReplace) {
    const { data: uid } = await db.rpc("partner_login_free", { p_email: email, p_partner: partnerId });
    if (uid && !(await db.auth.admin.deleteUser(String(uid))).error) gen = await db.auth.admin.generateLink({ type: "invite", email, options: { redirectTo: portal } });
  }
  if (gen.error) {
    if (!/already|registered|exists/i.test(gen.error.message)) throw gen.error;
    gen = await db.auth.admin.generateLink({ type: "recovery", email, options: { redirectTo: portal } });
    kind = "reset";
    if (gen.error) throw gen.error;
  }
  const link = (gen.data as { properties?: { action_link?: string } }).properties?.action_link;
  if (!link) throw new Error("no_link");
  return { link, kind };
}

