async function signup(req: Request, b: Row) {
  // quiet drop for bots (hidden field filled or form sent too fast)
  if (clip(b.website, 200) || Number(b.elapsed) < 2500) return { ok: true };
  const name = clip(b.name, 120), email = clip(b.email, 200).toLowerCase(), phone = clip(b.phone, 20);
  const type = TYPES.includes(b.partner_type) ? b.partner_type : null, lang = L(b.language), mt = ["video", "phone", "whatsapp"].includes(b.meeting_type) ? b.meeting_type : "video";
  const slot = new Date(String(b.slot || "")), tz = clip(b.timezone, 64);
  if (name.length < 2) throw new Fail("invalid_name");
  if (!EMAIL_RX.test(email)) throw new Fail("invalid_email");
  if (!/^\+[1-9][0-9]{6,14}$/.test(phone)) throw new Fail("invalid_phone");
  if (!type) throw new Fail("invalid_type");
  if (isNaN(slot.getTime()) || slot.getTime() < Date.now()) throw new Fail("slot_unavailable");
  if (b.consent !== true) throw new Fail("consent_required");
  // rate limits: per network address and overall
  const ip = (req.headers.get("x-forwarded-for") || "").split(",")[0].trim() || req.headers.get("cf-connecting-ip") || "unknown";
  const ipHash = await sha256("endeavor-partners:" + ip);
  const hourAgo = new Date(Date.now() - 3600e3).toISOString(), dayAgo = new Date(Date.now() - 864e5).toISOString();
  const [r1, r2] = await Promise.all([db.from("partner_signups").select("id", { count: "exact", head: true }).eq("ip_hash", ipHash).gte("created_at", hourAgo),
    db.from("partner_signups").select("id", { count: "exact", head: true }).gte("created_at", dayAgo)]);
  if ((r1.count ?? 0) >= 5 || (r2.count ?? 0) >= 60) throw new Fail("rate_limited", 429);
  await db.from("partner_signups").insert({ ip_hash: ipHash, email });
  const { data: dup } = await db.from("partners").select("id").eq("email", email).limit(1);
  if (dup?.length) throw new Fail("already_registered", 409);
  const { data: adm } = await db.from("admins").select("email").eq("email", email).limit(1);
  if (adm?.length) throw new Fail("email_in_use", 409);
  // onboarding call (the booking sends its own confirmation and reminders)
  const bk = await db.rpc("book_slot_v2", { p_starts_at: slot.toISOString(), p_name: name, p_email: email, p_phone: phone, p_topic: "Partner onboarding",
    p_notes: clip("Cadastro no Programa de Parceiros. " + (TYPE_PT[type] || "") + (b.company ? " · " + clip(b.company, 200) : "") + (b.notes ? "\n" + clip(b.notes, 1500) : ""), 2000), p_meeting_type: mt, p_language: lang, p_timezone: tz });
  if (bk.error) { const m = bk.error.message || ""; const k = ["slot_unavailable", "too_many_bookings", "invalid_phone", "invalid_email", "invalid_name"].find((x) => m.includes(x)); throw new Fail(k || "booking_failed", k ? 409 : 500); }
  const booking = (Array.isArray(bk.data) ? bk.data[0] : bk.data) as Row;
  const { data: p, error } = await db.from("partners").insert({ name, email, phone, company: clip(b.company, 200) || null, partner_type: type, language: lang, country: clip(b.country, 100) || null,
    notes: clip((b.notes ? "Sobre os clientes: " + clip(b.notes, 1500) + "\n" : "") + "Cadastro pelo site em " + now().slice(0, 10) + ".", 5000), status: "invited", program_status: "pending", default_share_pct: null,
    signup_source: "site", onboarding_booking_id: booking?.booking_id || null, onboarding_at: booking?.starts_at || slot.toISOString() }).select("*").single();
  if (error) {
    if (booking?.booking_id) await db.from("bookings").update({ status: "cancelled", cancelled_at: now(), cancelled_by: "admin", cancel_reason: "Cadastro de parceiro não concluído" }).eq("id", booking.booking_id);
    throw error;
  }
  const whenEt = fmtWhen(p.onboarding_at, "pt", "America/New_York");
  let mailed = false;
  try {
    if (SMTP_PASS.length >= 8) {
      const portal = `${SITE}/partner.html?lang=${lang}`;
      const { link } = await accessLink(email, portal, true, p.id);
      const w = W[lang], first = name.split(" ")[0];
      const body = P_(f(w.hi, first)) + P_(w.intro) + BOX(esc(w.call) + ":<br>" + esc(fmtWhen(p.onboarding_at, lang, tz))) + `<p style="margin:0 0 6px;font-size:13px;color:#6b7280">${esc(w.resched)}</p>` +
        H_(w.next) + STEPS([[w.s1, w.s1d], [w.s2, w.s2d, w.s2n], [w.s3, w.s3d], [w.s4, w.s4d]]);
      const text = [f(w.hi, first), "", w.intro, "", w.call + ": " + fmtWhen(p.onboarding_at, lang, tz), "", w.next.toUpperCase(), "1. " + w.s1 + ": " + w.s1d, "2. " + w.s2 + ": " + w.s2d + " " + w.s2n,
        "3. " + w.s3 + ": " + w.s3d, "4. " + w.s4 + ": " + w.s4d, "", w.cta + ": " + link, (T[lang] as Record<string, string>).ctaNote, "", (T[lang] as Record<string, string>).sign, SMTP_USER + " · " + PHONE].join("\n");
      await mailer().sendMail({ from: { name: FROM_NAME, address: SMTP_USER }, to: email, bcc: SMTP_USER, replyTo: SMTP_USER, subject: f(w.subject, first),
        html: shell(lang, { title: f(w.subject, first), kicker: w.kicker, h1: w.h1, pre: w.pre, body, cta: w.cta, url: link, note: (T[lang] as Record<string, string>).ctaNote }), text });
      mailed = true;
    }
  } catch (e) { console.error("welcome", e); }
  await bell("partner_new", "Novo parceiro (cadastro pelo site): " + name, [TYPE_PT[type], p.company, p.country].filter(Boolean).join(" · ") + " · Onboarding: " + whenEt + " (Orlando)" +
    (mailed ? "" : " · O e-mail de boas-vindas não saiu: use \"Reenviar convite\"."), "#/parceiros?id=" + p.id);
  return { ok: true, starts_at: booking?.starts_at || null, ends_at: booking?.ends_at || null };
}

/* ---------- partner agreement ---------- */
function contractData(p: Row, pct: number, sentAt: string) {
  return { date_text: new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", dateStyle: "long" }).format(new Date(sentAt)), pct,
    partner: { name: p.name, company: p.company || "", email: p.email, country: p.country || "", type: p.partner_type } };
}
const signUrl = (token: string, lang: string, ret: string) => `${SITE}/sign.html?t=${token}&lang=${lang}&ret=${ret}`;
async function mailContract(p: Row, token: string) {
  const lang = L(p.language), c = C[lang], pct = (Math.round(Number(p.contract_pct) * 100) / 100) + "%", url = signUrl(token, lang, "partner");
  const body = P_(f((T[lang] as Record<string, string>).hi, String(p.name).split(" ")[0])) + P_(c.body.replace("{pct}", pct)) + P_(c.body2);
  await mailer().sendMail({ from: { name: FROM_NAME, address: SMTP_USER }, to: p.email, bcc: SMTP_USER, replyTo: SMTP_USER, subject: c.subject,
    html: shell(lang, { title: c.subject, kicker: W[lang].kicker, h1: c.h1, pre: c.pre, body, cta: c.cta, url, note: c.note }),
    text: [f((T[lang] as Record<string, string>).hi, String(p.name).split(" ")[0]), "", c.body.replace("{pct}", pct), c.body2, "", c.cta + ": " + url, c.note].join("\n") });
}
async function mailCountersign(p: Row, token: string) {
  const url = signUrl(token, "pt", "admin");
  await mailer().sendMail({ from: { name: FROM_NAME, address: SMTP_USER }, to: SMTP_USER, subject: "Assinar pela Endeavor: contrato de parceria de " + p.name,
    text: `O parceiro ${p.name} (${p.email}) assinou o contrato de parceria (comissão ${p.contract_pct}%).\n\nAssine pela Endeavor: ${url}\n\nO link também está no admin: Parceiros → ${p.name} → Contrato.` });
}
async function sendContract(p: Row, pct: number, by: string) {
  for (const id of [p.contract_partner_env, p.contract_endeavor_env].filter(Boolean)) {
    const { data: e } = await db.from("envelopes").select("id, status").eq("id", id).maybeSingle();
    if (e && !["signed", "voided"].includes(e.status)) { await db.from("envelopes").update({ status: "voided" }).eq("id", e.id); await db.from("envelope_events").insert({ envelope_id: e.id, event: "voided", details: { by, reason: "new_partner_agreement" } }); }
  }
  const v = (p.contract_version || 0) + 1, sentAt = now();
  const doc = await (globalThis as Row).EPContract.render(PDFLib, contractData(p, pct, sentAt));
  const sha = await sha256(doc.bytes), path = `partners/${p.id}/agreement-v${v}.pdf`;
  const up = await db.storage.from("documents").upload(path, doc.bytes, { contentType: "application/pdf", upsert: true }); if (up.error) throw up.error;
  const { data: env, error } = await db.from("envelopes").insert({ title: ("Referral Partner Agreement - " + p.name).slice(0, 200), signer_name: p.name, signer_email: p.email,
    message: "Endeavor Partner Program agreement (commission " + pct + "%). Signer 1 of 2: Partner.", document_path: path, document_sha256: sha,
    fields: doc.fields.filter((x: Row) => x.signer === 0).map(({ signer: _s, ...x }: Row) => x), id_stamped: false, created_by: "partner-program" }).select("*").single();
  if (error) throw error;
  await db.from("envelope_events").insert({ envelope_id: env.id, event: "sent", details: { partner_id: p.id, version: v } });
  const upd = { contract_status: "sent", contract_pct: pct, contract_version: v, contract_sent_at: sentAt, contract_partner_env: env.id, contract_partner_token: env.token,
    contract_endeavor_env: null, contract_signed_at: null, contract_signed_path: null };
  await db.from("partners").update(upd).eq("id", p.id);
  Object.assign(p, upd);
  let mailed = false;
  try { if (SMTP_PASS.length >= 8) { await mailContract(p, env.token); mailed = true; await db.from("envelope_events").insert({ envelope_id: env.id, event: "emailed", details: { to: p.email, via: "partner-program" } }); } } catch (e) { console.error("contract mail", e); }
  return { ok: true, version: v, mailed };
}
async function envelopeSigned(token: string) {
  if (!/^[0-9a-f-]{36}$/i.test(token)) return { ok: false };
  const { data: env } = await db.from("envelopes").select("*").eq("token", token).maybeSingle();
  if (!env || env.status !== "signed") return { ok: false };
  const { data: p } = await db.from("partners").select("*").or(`contract_partner_env.eq.${env.id},contract_endeavor_env.eq.${env.id}`).maybeSingle();
  if (!p) return { ok: false };
  if (p.contract_partner_env === env.id && p.contract_status === "sent") {
    const doc = await (globalThis as Row).EPContract.render(PDFLib, contractData(p, Number(p.contract_pct), p.contract_sent_at));
    const { data: e2, error } = await db.from("envelopes").insert({ title: ("Referral Partner Agreement - " + p.name + " (Endeavor)").slice(0, 200), signer_name: "Endeavor Business Solutions", signer_email: SMTP_USER,
      message: "Countersignature by Endeavor. Signer 2 of 2.", document_path: env.signed_document_path, document_sha256: env.signed_document_sha256,
      fields: doc.fields.filter((x: Row) => x.signer === 1).map(({ signer: _s, ...x }: Row) => x), id_stamped: true, created_by: "partner-program" }).select("*").single();
    if (error) throw error;
    await db.from("envelope_events").insert({ envelope_id: e2.id, event: "sent", details: { partner_id: p.id, countersign: true } });
    await db.from("partners").update({ contract_status: "partner_signed", contract_endeavor_env: e2.id }).eq("id", p.id).eq("contract_status", "sent");
    await bell("partner_contract", "Contrato assinado pelo parceiro: " + p.name, "Falta a assinatura da Endeavor. Abra o parceiro → Contrato → Assinar pela Endeavor.", "#/parceiros?id=" + p.id + "&tab=contrato");
    try { if (SMTP_PASS.length >= 8) await mailCountersign(p, e2.token); } catch (e) { console.error("countersign mail", e); }
    return { ok: true, step: "partner_signed" };
  }
  if (p.contract_endeavor_env === env.id && p.contract_status === "partner_signed") {
    await db.from("partners").update({ contract_status: "signed", contract_signed_at: env.signed_at, contract_signed_path: env.signed_document_path }).eq("id", p.id);
    await bell("partner_contract", "Contrato de parceria concluído: " + p.name, "Assinado pelas duas partes. Cópia no parceiro → Contrato e em Assinaturas.", "#/parceiros?id=" + p.id + "&tab=contrato");
    try {
      if (SMTP_PASS.length >= 8) {
        const lang = L(p.language), d = D[lang], url = `${SITE}/partner.html?lang=${lang}`;
        const body = P_(f((T[lang] as Record<string, string>).hi, String(p.name).split(" ")[0])) + P_(d.body) + P_(d.body2);
        await mailer().sendMail({ from: { name: FROM_NAME, address: SMTP_USER }, to: p.email, bcc: SMTP_USER, replyTo: SMTP_USER, subject: d.subject,
          html: shell(lang, { title: d.subject, kicker: W[lang].kicker, h1: d.h1, pre: d.pre, body, cta: d.cta, url }), text: [d.body, d.body2, "", d.cta + ": " + url].join("\n") });
      }
    } catch (e) { console.error("done mail", e); }
    return { ok: true, step: "signed" };
  }
  return { ok: true, step: "none" };
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
  if (req.method !== "POST") return json({ error: "method" }, 405);
  try {
    const body = await req.json().catch(() => ({}));
    // public: self sign-up from partners.html, and the hook called by sign.html after a signature
    if (body.action === "signup") return json(await signup(req, body));
    if (body.action === "envelope_signed") return json(await envelopeSigned(String(body.token || "")));

    const user = createClient(SB_URL, SB_ANON || SB_SERVICE, { global: { headers: { Authorization: req.headers.get("Authorization") ?? "" } }, auth: { persistSession: false } });
    const { data: isAdmin } = await user.rpc("is_admin");

    // signed agreement download (the partner for their own, or an admin)
    if (body.action === "contract_url") {
      let pid: string | null = null;
      if (isAdmin) pid = String(body.partner_id || "");
      else { const { data: mine } = await user.rpc("my_partner_id"); pid = (mine as string) || null; }
      if (!pid) return json({ error: "forbidden" }, 403);
      const { data: cp } = await db.from("partners").select("contract_signed_path, contract_partner_env").eq("id", pid).single();
      let path = cp?.contract_signed_path || null;
      if (!path && cp?.contract_partner_env) { const { data: e } = await db.from("envelopes").select("signed_document_path").eq("id", cp.contract_partner_env).maybeSingle(); path = e?.signed_document_path || null; }
      if (!path) return json({ error: "not_signed" }, 404);
      const { data: su, error } = await db.storage.from("documents").createSignedUrl(path, 600);
      if (error) throw error;
      return json({ url: su.signedUrl });
    }

    if (!isAdmin) return json({ error: "forbidden" }, 403);
    const { data: me } = await user.auth.getUser();
    const adminEmail = me?.user?.email || "admin";
    const { data: p } = await db.from("partners").select("*").eq("id", String(body.partner_id || "")).single();
    if (!p) return json({ error: "not_found" }, 404);

    if (body.action === "approve") {
      const pct = Number(body.pct);
      if (!(pct >= 0 && pct <= 100)) return json({ error: "invalid_share" }, 400);
      await db.from("partners").update({ default_share_pct: pct, program_status: "approved", approved_at: now(), approved_by: adminEmail }).eq("id", p.id);
      Object.assign(p, { default_share_pct: pct, program_status: "approved" });
      const r = body.send_contract === false ? { ok: true, contract: false } : await sendContract(p, pct, adminEmail);
      return json({ ...r, ok: true });
    }
    if (body.action === "contract_send") {
      const pct = body.pct != null ? Number(body.pct) : Number(p.default_share_pct);
      if (!(pct >= 0 && pct <= 100)) return json({ error: "invalid_share" }, 400);
      return json(await sendContract(p, pct, adminEmail));
    }
    if (body.action === "contract_resend") {
      if (SMTP_PASS.length < 8) return json({ error: "smtp_not_configured" }, 503);
      if (p.contract_status === "sent" && p.contract_partner_token) { await mailContract(p, p.contract_partner_token); return json({ ok: true, to: p.email }); }
      if (p.contract_status === "partner_signed" && p.contract_endeavor_env) {
        const { data: e } = await db.from("envelopes").select("token").eq("id", p.contract_endeavor_env).single();
        await mailCountersign(p, e!.token); return json({ ok: true, to: SMTP_USER });
      }
      return json({ error: "nothing_to_send" }, 400);
    }

    // delete a partner and its login, so the same e-mail can be invited again as a new partner
    if (body.action === "delete") {
      const [r1, r2] = await Promise.all([db.from("referrals").select("id", { count: "exact", head: true }).eq("partner_id", p.id), db.from("invoices").select("id", { count: "exact", head: true }).eq("partner_id", p.id)]);
      if ((r1.count ?? 0) > 0 || (r2.count ?? 0) > 0) return json({ error: "has_history" }, 409);
      const { data: uid } = await db.rpc("partner_login_free", { p_email: p.email, p_partner: p.id });
      const del = await db.from("partners").delete().eq("id", p.id);
      if (del.error) throw del.error;
      let loginDeleted = false;
      if (uid) { const d = await db.auth.admin.deleteUser(String(uid)); loginDeleted = !d.error; }
      return json({ ok: true, login_deleted: loginDeleted });
    }
    if (SMTP_PASS.length < 8) return json({ error: "smtp_not_configured" }, 503);
    const lang = L(p.language), portal = `${SITE}/partner.html?lang=${lang}`;
    // secure link to create the password: invite for a new login, recovery when the login already exists
    let gen = await db.auth.admin.generateLink({ type: "invite", email: p.email, options: { redirectTo: portal } });
    let kind = "invite";
    if (gen.error && /already|registered|exists/i.test(gen.error.message) && p.status !== "active") {
      // a login left over from a deleted partner (not an admin, client or other partner): start fresh with a new invitation
      const { data: uid } = await db.rpc("partner_login_free", { p_email: p.email, p_partner: p.id });
      if (uid && !(await db.auth.admin.deleteUser(String(uid))).error) gen = await db.auth.admin.generateLink({ type: "invite", email: p.email, options: { redirectTo: portal } });
    }
    if (gen.error) {
      if (!/already|registered|exists/i.test(gen.error.message)) throw gen.error;
      gen = await db.auth.admin.generateLink({ type: "recovery", email: p.email, options: { redirectTo: portal } });
      kind = "reset";
      if (gen.error) throw gen.error;
    }
    const link = (gen.data as { properties?: { action_link?: string } }).properties?.action_link;
    if (!link) throw new Error("no_link");
    const first = String(p.name || "").split(" ")[0] || p.name;
    const t = T[lang] as Record<string, string>;
    const tr = nodemailer.createTransport({ host: SMTP_HOST, port: 465, secure: true, auth: { user: SMTP_USER, pass: SMTP_PASS } });
    await tr.sendMail({ from: { name: FROM_NAME, address: SMTP_USER }, to: p.email, bcc: SMTP_USER, replyTo: SMTP_USER, subject: f(t.subject, first),
      html: emailHtml(lang, first, link, portal), text: emailText(lang, first, link, portal) });
    await db.from("partners").update({ invited_at: new Date().toISOString() }).eq("id", p.id);
    return json({ ok: true, sent: kind });
  } catch (e) {
    if (e instanceof Fail) return json({ error: e.code }, e.status);
    console.error(e);
    return json({ error: String((e as Error).message || e).slice(0, 300) }, 500);
  }
});
